CREATE TABLE public.partner_customers (patient_id uuid PRIMARY KEY REFERENCES public.patients(id),partner_id uuid NOT NULL REFERENCES public.partners(id),location_id uuid NOT NULL REFERENCES public.locations(id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.partner_customers TO authenticated; GRANT ALL ON public.partner_customers TO service_role; ALTER TABLE public.partner_customers ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.partner_screening_configs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),partner_id uuid NOT NULL REFERENCES public.partners(id),version integer NOT NULL,settings jsonb NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(partner_id,version));
GRANT SELECT ON public.partner_screening_configs TO authenticated; GRANT ALL ON public.partner_screening_configs TO service_role; ALTER TABLE public.partner_screening_configs ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.partner_intakes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),patient_id uuid NOT NULL REFERENCES public.partner_customers(patient_id),partner_id uuid NOT NULL REFERENCES public.partners(id),location_id uuid NOT NULL REFERENCES public.locations(id),config_id uuid REFERENCES public.partner_screening_configs(id),evidence jsonb NOT NULL,gates jsonb NOT NULL,status text NOT NULL CHECK(status IN ('BLOCKED','MANUAL_REVIEW','READY','CREATING','REQUESTED','REJECTED')),evaluated_by uuid NOT NULL,evaluated_at timestamptz NOT NULL DEFAULT now(),reason text NOT NULL,consultation_id uuid UNIQUE REFERENCES public.consultations(id),creation_tx text,emergency boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.partner_intakes TO authenticated; GRANT ALL ON public.partner_intakes TO service_role; ALTER TABLE public.partner_intakes ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.partner_intake_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),partner_id uuid NOT NULL REFERENCES public.partners(id),patient_id uuid NOT NULL REFERENCES public.patients(id),intake_id uuid REFERENCES public.partner_intakes(id),actor_user_id uuid NOT NULL,action text NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.partner_intake_events TO authenticated; GRANT ALL ON public.partner_intake_events TO service_role; ALTER TABLE public.partner_intake_events ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.partner_customer_write(_u uuid,_p uuid,_l uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _u IS NOT NULL AND EXISTS(SELECT 1 FROM partners WHERE id=_p AND status='ACTIVE') AND partner_workspace_enabled(_p) AND EXISTS(SELECT 1 FROM locations WHERE id=_l AND partner_id=_p AND status='ACTIVE') AND EXISTS(SELECT 1 FROM user_roles r WHERE r.user_id=_u AND r.partner_id=_p AND r.status='ACTIVE' AND (r.role IN ('PARTNER_OWNER','PARTNER_MANAGER') OR (r.role='PARTNER_STAFF' AND EXISTS(SELECT 1 FROM care_branch_permissions b WHERE b.user_id=_u AND b.partner_id=_p AND b.location_id=_l AND b.queue_allowed)))) $$;
CREATE FUNCTION public.partner_customer_read(_patient uuid,_u uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM partner_customers c WHERE c.patient_id=_patient AND (partner_customer_write(_u,c.partner_id,c.location_id) OR partner_review_scope(_u,c.partner_id) OR EXISTS(SELECT 1 FROM partner_intakes i JOIN consultations e ON e.id=i.consultation_id JOIN doctors d ON d.id=e.assigned_doctor_id JOIN doctor_assignments a ON a.doctor_id=d.id AND a.partner_id=c.partner_id AND (a.location_id IS NULL OR a.location_id=c.location_id) JOIN user_roles r ON r.user_id=_u AND r.role='DOCTOR' AND r.status='ACTIVE' AND (r.partner_id IS NULL OR r.partner_id=c.partner_id) WHERE i.patient_id=c.patient_id AND d.auth_user_id=_u AND d.status='ACTIVE' AND a.status='ACTIVE'))) $$;
CREATE FUNCTION public.partner_screening_editor(_u uuid,_p uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM user_roles WHERE user_id=_u AND role='COMPLIANCE_AUDITOR' AND status='ACTIVE' AND (partner_id IS NULL OR partner_id=_p)) OR EXISTS(SELECT 1 FROM doctors d JOIN doctor_assignments a ON a.doctor_id=d.id JOIN user_roles r ON r.user_id=_u AND r.role='DOCTOR' AND r.status='ACTIVE' AND (r.partner_id IS NULL OR r.partner_id=_p) WHERE d.auth_user_id=_u AND d.status='ACTIVE' AND a.partner_id=_p AND a.status='ACTIVE') $$;
CREATE FUNCTION public.partner_customer_enrolled(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM partner_customers WHERE patient_id=_id) $$;
REVOKE ALL ON FUNCTION public.partner_customer_write(uuid,uuid,uuid),public.partner_customer_read(uuid,uuid),public.partner_screening_editor(uuid,uuid),public.partner_customer_enrolled(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.partner_customer_write(uuid,uuid,uuid),public.partner_customer_read(uuid,uuid),public.partner_screening_editor(uuid,uuid),public.partner_customer_enrolled(uuid) TO authenticated,service_role;
CREATE POLICY partner_customer_read ON public.partner_customers FOR SELECT TO authenticated USING(partner_customer_read(patient_id,auth.uid()));
CREATE POLICY partner_config_read ON public.partner_screening_configs FOR SELECT TO authenticated USING(partner_screening_editor(auth.uid(),partner_id) OR partner_review_scope(auth.uid(),partner_id) OR EXISTS(SELECT 1 FROM locations l WHERE l.partner_id=partner_screening_configs.partner_id AND partner_customer_write(auth.uid(),l.partner_id,l.id)));
CREATE POLICY partner_intake_read ON public.partner_intakes FOR SELECT TO authenticated USING(partner_customer_read(patient_id,auth.uid()));
CREATE POLICY partner_intake_event_read ON public.partner_intake_events FOR SELECT TO authenticated USING(partner_customer_read(patient_id,auth.uid()));
CREATE POLICY partner_customer_patient_read ON public.patients AS RESTRICTIVE FOR SELECT TO authenticated USING(NOT partner_customer_enrolled(id) OR partner_customer_read(id,auth.uid()));
CREATE POLICY partner_customer_patient_update ON public.patients AS RESTRICTIVE FOR UPDATE TO authenticated USING(NOT partner_customer_enrolled(id)) WITH CHECK(NOT partner_customer_enrolled(id));
CREATE POLICY partner_customer_patient_delete ON public.patients AS RESTRICTIVE FOR DELETE TO authenticated USING(NOT partner_customer_enrolled(id));
CREATE FUNCTION public.partner_customer_identity_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF partner_customer_enrolled(NEW.id) AND (NEW.auth_user_id IS NOT NULL OR NEW.partner_id IS DISTINCT FROM OLD.partner_id) THEN RAISE EXCEPTION 'CUSTOMER_NON_LOGIN_SCOPE_REQUIRED'; END IF; RETURN NEW; END $$;
CREATE TRIGGER partner_customer_identity BEFORE UPDATE ON public.patients FOR EACH ROW EXECUTE FUNCTION public.partner_customer_identity_guard();
CREATE FUNCTION public.partner_intake_consultation_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c partner_customers; BEGIN IF TG_OP='UPDATE' AND partner_customer_enrolled(OLD.patient_id) AND NEW.patient_id IS DISTINCT FROM OLD.patient_id THEN RAISE EXCEPTION 'CUSTOMER_BRANCH_SCOPE_REQUIRED'; END IF; SELECT * INTO c FROM partner_customers WHERE patient_id=NEW.patient_id; IF c.patient_id IS NULL THEN RETURN NEW; END IF; IF NEW.partner_id<>c.partner_id OR NEW.care_location_id IS DISTINCT FROM c.location_id THEN RAISE EXCEPTION 'CUSTOMER_BRANCH_SCOPE_REQUIRED'; END IF; IF TG_OP='INSERT' AND NOT EXISTS(SELECT 1 FROM partner_intakes WHERE patient_id=c.patient_id AND status='CREATING' AND creation_tx=txid_current()::text) THEN RAISE EXCEPTION 'SCREENING_REQUIRED'; END IF; IF NEW.assigned_doctor_id IS NOT NULL THEN IF NOT EXISTS(SELECT 1 FROM doctors d JOIN doctor_assignments a ON a.doctor_id=d.id JOIN user_roles r ON r.user_id=d.auth_user_id AND r.role='DOCTOR' AND r.status='ACTIVE' AND (r.partner_id IS NULL OR r.partner_id=c.partner_id) WHERE d.id=NEW.assigned_doctor_id AND d.status='ACTIVE' AND d.license_expires_on>=current_date AND a.status='ACTIVE' AND a.partner_id=c.partner_id AND (a.location_id IS NULL OR a.location_id=c.location_id)) THEN RAISE EXCEPTION 'DOCTOR_BRANCH_SCOPE_REQUIRED'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER partner_intake_consultation BEFORE INSERT OR UPDATE OF patient_id,partner_id,care_location_id,assigned_doctor_id ON public.consultations FOR EACH ROW EXECUTE FUNCTION public.partner_intake_consultation_guard();
CREATE POLICY partner_intake_encounter_read ON public.consultations AS RESTRICTIVE FOR SELECT TO authenticated USING(NOT partner_customer_enrolled(patient_id) OR partner_customer_read(patient_id,auth.uid()));
CREATE POLICY partner_customer_consent_read ON public.patient_consents AS RESTRICTIVE FOR SELECT TO authenticated USING(NOT partner_customer_enrolled(patient_id) OR partner_customer_read(patient_id,auth.uid()));
CREATE POLICY partner_customer_history_read ON public.patient_intakes AS RESTRICTIVE FOR SELECT TO authenticated USING(NOT partner_customer_enrolled(patient_id) OR partner_customer_read(patient_id,auth.uid()));
CREATE FUNCTION public.partner_intake_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'APPEND_ONLY'; END $$;
CREATE TRIGGER partner_intake_events_immutable BEFORE UPDATE OR DELETE ON public.partner_intake_events FOR EACH ROW EXECUTE FUNCTION public.partner_intake_immutable();
CREATE TRIGGER partner_screening_configs_immutable BEFORE UPDATE OR DELETE ON public.partner_screening_configs FOR EACH ROW EXECUTE FUNCTION public.partner_intake_immutable();
CREATE FUNCTION public.partner_intake_command(_op text,_id uuid DEFAULT NULL,_args jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE u uuid:=auth.uid(); p uuid; l uuid; c partner_customers; cfg partner_screening_configs; i partner_intakes; e jsonb; g jsonb:='[]'; v text; checks boolean[]; reasons text[]; n int; cid uuid; res jsonb; why text:=btrim(coalesce(_args->>'reason','')); emer boolean:=false;
BEGIN
IF u IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
IF jsonb_typeof(_args)<>'object' OR length(_args::text)>24000 OR length(why)>1000 THEN RAISE EXCEPTION 'INVALID_INPUT'; END IF;
IF _op='CONFIGURE' THEN
p:=(_args->>'partnerId')::uuid; IF NOT partner_screening_editor(u,p) THEN RAISE EXCEPTION 'CLINICIAN_COMPLIANCE_REQUIRED'; END IF; PERFORM care_require_strong(); PERFORM 1 FROM partners WHERE id=p FOR UPDATE; e:=_args->'settings';
IF jsonb_typeof(e) IS DISTINCT FROM 'object' OR coalesce(e->>'minimumAge','') !~ '^\d{1,3}$' OR (e->>'minimumAge')::int>120 OR length(coalesce(e->>'consentVersion','')) NOT BETWEEN 1 AND 100 OR why='' THEN RAISE EXCEPTION 'INVALID_CONFIGURATION'; END IF;
FOREACH v IN ARRAY ARRAY['redFlags','exclusions','serviceReasons','jurisdictions'] LOOP
IF jsonb_typeof(e->v) IS DISTINCT FROM 'array' OR jsonb_array_length(e->v)>100 OR (v IN ('serviceReasons','jurisdictions') AND jsonb_array_length(e->v)=0) THEN RAISE EXCEPTION 'INVALID_CONFIGURATION'; END IF;
IF EXISTS(SELECT 1 FROM jsonb_array_elements(e->v) x WHERE jsonb_typeof(x)<>'string' OR length(x#>>'{}') NOT BETWEEN 1 AND 200) THEN RAISE EXCEPTION 'INVALID_CONFIGURATION'; END IF;
END LOOP;
INSERT INTO partner_screening_configs(partner_id,version,settings,created_by) VALUES(p,coalesce((SELECT max(version)+1 FROM partner_screening_configs WHERE partner_id=p),1),e,u) RETURNING * INTO cfg;
INSERT INTO audit_log(actor_user_id,partner_id,action,entity_type,entity_id,metadata) VALUES(u,p,'SCREENING_CONFIGURED','screening_config',cfg.id::text,jsonb_build_object('version',cfg.version)); RETURN jsonb_build_object('id',cfg.id);
END IF;
IF _op='CUSTOMER_SAVE' THEN
IF _id IS NOT NULL THEN SELECT * INTO c FROM partner_customers WHERE patient_id=_id FOR UPDATE; p:=c.partner_id;l:=c.location_id; ELSE p:=(_args->>'partnerId')::uuid;l:=(_args->>'locationId')::uuid; END IF;
IF NOT coalesce(partner_customer_write(u,p,l),false) THEN RAISE EXCEPTION 'PARTNER_BRANCH_REQUIRED'; END IF;
IF length(btrim(coalesce(_args->>'firstName',''))) NOT BETWEEN 1 AND 100 OR length(btrim(coalesce(_args->>'lastName',''))) NOT BETWEEN 1 AND 100 OR length(coalesce(_args->>'phone',''))>40 OR length(coalesce(_args->>'email',''))>255 OR (coalesce(_args->>'email','')<>'' AND (_args->>'email') !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') THEN RAISE EXCEPTION 'INVALID_CUSTOMER'; END IF;
IF _id IS NULL THEN INSERT INTO patients(partner_id,first_name,last_name,email,phone_number) VALUES(p,btrim(_args->>'firstName'),btrim(_args->>'lastName'),nullif(_args->>'email',''),nullif(_args->>'phone','')) RETURNING id INTO _id; INSERT INTO partner_customers(patient_id,partner_id,location_id,created_by) VALUES(_id,p,l,u);
ELSE UPDATE patients SET first_name=btrim(_args->>'firstName'),last_name=btrim(_args->>'lastName'),email=nullif(_args->>'email',''),phone_number=nullif(_args->>'phone',''),updated_at=now() WHERE id=_id; END IF;
UPDATE partner_intakes SET status='MANUAL_REVIEW' WHERE patient_id=_id AND status='READY'; INSERT INTO partner_intake_events(partner_id,patient_id,actor_user_id,action,reason) VALUES(p,_id,u,'CUSTOMER_SAVED',coalesce(nullif(why,''),'Customer details saved')); RETURN jsonb_build_object('id',_id);
END IF;
IF _op='ASSESS' THEN SELECT * INTO c FROM partner_customers WHERE patient_id=_id FOR UPDATE; ELSE SELECT * INTO i FROM partner_intakes WHERE id=_id FOR UPDATE; SELECT * INTO c FROM partner_customers WHERE patient_id=i.patient_id FOR UPDATE; END IF;
IF c.patient_id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND'; END IF; p:=c.partner_id;l:=c.location_id;
IF _op='REJECT' THEN IF NOT partner_review_scope(u,p) THEN RAISE EXCEPTION 'REVIEWER_REQUIRED'; END IF; PERFORM care_require_strong(); IF why='' OR i.status NOT IN ('BLOCKED','MANUAL_REVIEW','READY') THEN RAISE EXCEPTION 'INVALID_TRANSITION'; END IF; UPDATE partner_intakes SET status='REJECTED' WHERE id=i.id;
ELSE
IF NOT partner_customer_write(u,p,l) THEN RAISE EXCEPTION 'PARTNER_BRANCH_REQUIRED'; END IF;
IF _op='ASSESS' THEN
 e:=_args->'evidence'; IF jsonb_typeof(e) IS DISTINCT FROM 'object' OR why='' THEN RAISE EXCEPTION 'EVIDENCE_REASON_REQUIRED'; END IF;
 UPDATE partner_intakes SET status='MANUAL_REVIEW' WHERE patient_id=c.patient_id AND status='READY';
 SELECT * INTO cfg FROM partner_screening_configs WHERE partner_id=p ORDER BY version DESC LIMIT 1;
 IF cfg.id IS NOT NULL THEN FOREACH v IN ARRAY ARRAY['redFlags','exclusions'] LOOP IF jsonb_typeof(e->v) IS DISTINCT FROM 'array' OR EXISTS(SELECT 1 FROM jsonb_array_elements(e->v) x WHERE NOT (cfg.settings->v @> jsonb_build_array(x))) THEN RAISE EXCEPTION 'INVALID_FLAG_EVIDENCE'; END IF; END LOOP; emer:=jsonb_array_length(e->'redFlags')>0; END IF;
 checks:=ARRAY[
 cfg.id IS NOT NULL AND NOT emer AND e->>'redFlagsReviewed'='true' AND e->>'telemedicineSuitable'='true',
 cfg.id IS NOT NULL AND e->>'identityVerified'='true' AND e->>'contactVerified'='true' AND CASE WHEN coalesce(e->>'age','') ~ '^\d{1,3}$' THEN (e->>'age')::int BETWEEN 0 AND 120 AND ((e->>'age')::int >= (cfg.settings->>'minimumAge')::int OR e->>'guardianVerified'='true') ELSE false END AND cfg.settings->'jurisdictions' @> jsonb_build_array(e->>'jurisdiction') AND e->>'telemedicineConsent'='true' AND e->>'privacyConsent'='true' AND e->>'consentVersion'=cfg.settings->>'consentVersion',
 cfg.id IS NOT NULL AND cfg.settings->'serviceReasons' @> jsonb_build_array(e->>'serviceReason') AND jsonb_array_length(e->'exclusions')=0 AND e->>'exclusionsReviewed'='true' AND length(btrim(coalesce(e->>'history','')))>0 AND length(btrim(coalesce(e->>'medicines','')))>0 AND length(btrim(coalesce(e->>'allergies','')))>0 AND length(btrim(coalesce(e->>'riskFlags','')))>0,
 e->>'dataComplete'='true' AND e->>'communicationReady'='true' AND e->>'contactVerified'='true' AND e->>'nextStepReady'='true' AND e->>'channel' IN ('PHONE','VIDEO','IN_PERSON') AND EXISTS(SELECT 1 FROM patients WHERE id=c.patient_id AND (nullif(phone_number,'') IS NOT NULL OR nullif(email,'') IS NOT NULL)) AND EXISTS(SELECT 1 FROM doctors d JOIN doctor_assignments a ON a.doctor_id=d.id JOIN user_roles r ON r.user_id=d.auth_user_id AND r.role='DOCTOR' AND r.status='ACTIVE' AND (r.partner_id IS NULL OR r.partner_id=p) WHERE d.id=nullif(e->>'doctorId','')::uuid AND d.status='ACTIVE' AND d.license_expires_on>=current_date AND a.partner_id=p AND a.status='ACTIVE' AND (a.location_id IS NULL OR a.location_id=l))];
 reasons:=ARRAY['Emergency/red-flag review','Identity, age, jurisdiction and consent','Configured service scope and minimum clinical history','Communication, contact, Doctor/branch and next-step readiness'];
 IF jsonb_typeof(e->'gateReasons') IS DISTINCT FROM 'array' OR jsonb_array_length(e->'gateReasons')<>4 THEN RAISE EXCEPTION 'FOUR_REASONS_REQUIRED'; END IF;
 FOR n IN 1..4 LOOP IF length(btrim(coalesce(e->'gateReasons'->>(n-1),''))) NOT BETWEEN 1 AND 1000 THEN RAISE EXCEPTION 'FOUR_REASONS_REQUIRED'; END IF;
 g:=g||jsonb_build_array(jsonb_build_object('gate',n,'result',CASE WHEN coalesce(checks[n],false) THEN 'PASS' ELSE 'FAIL' END,'reason',e->'gateReasons'->>(n-1),'rule',reasons[n],'configId',cfg.id,'configVersion',cfg.version,'evaluator',u,'at',now())); END LOOP;
 INSERT INTO partner_intakes(patient_id,partner_id,location_id,config_id,evidence,gates,status,evaluated_by,reason,emergency) VALUES(c.patient_id,p,l,cfg.id,e,g,CASE WHEN emer THEN 'BLOCKED' WHEN NOT EXISTS(SELECT 1 FROM jsonb_array_elements(g) x WHERE x->>'result'='FAIL') THEN 'READY' ELSE 'MANUAL_REVIEW' END,u,why,emer) RETURNING * INTO i; _id:=i.id;
 ELSIF _op='REQUEST' THEN
 IF i.status='REQUESTED' THEN RETURN jsonb_build_object('id',i.id,'consultationId',i.consultation_id,'status',i.status); END IF;
 PERFORM 1 FROM partners WHERE id=p FOR UPDATE;
 IF i.status<>'READY' OR i.evaluated_at<now()-interval '24 hours' OR EXISTS(SELECT 1 FROM jsonb_array_elements(i.gates) x WHERE x->>'result'<>'PASS') OR i.evidence->>'telemedicineConsent'<>'true' OR i.evidence->>'privacyConsent'<>'true' OR i.config_id IS DISTINCT FROM (SELECT id FROM partner_screening_configs WHERE partner_id=p ORDER BY version DESC LIMIT 1) THEN RAISE EXCEPTION 'SCREENING_REQUIRED'; END IF;
 UPDATE partner_intakes SET status='CREATING',creation_tx=txid_current()::text WHERE id=i.id;
 INSERT INTO patient_consents(patient_id,consent_type,version,accepted,recorded_by) VALUES(c.patient_id,'TELEMEDICINE',i.evidence->>'consentVersion',true,u),(c.patient_id,'PRIVACY',i.evidence->>'consentVersion',true,u);
 res:=care_command('INTAKE',jsonb_build_object('partnerId',p,'patientId',c.patient_id,'locationId',l,'kind','PARTNER'),'partner-intake:'||i.id); cid:=(res->>'id')::uuid;
 UPDATE consultations SET assigned_doctor_id=(i.evidence->>'doctorId')::uuid WHERE id=cid;
 UPDATE partner_intakes SET status='REQUESTED',consultation_id=cid,creation_tx=NULL WHERE id=i.id RETURNING * INTO i;
 ELSE RAISE EXCEPTION 'UNKNOWN_OPERATION'; END IF;
END IF;
INSERT INTO partner_intake_events(partner_id,patient_id,intake_id,actor_user_id,action,reason) VALUES(p,c.patient_id,i.id,u,CASE WHEN _op='ASSESS' AND emer THEN 'EMERGENCY_ESCALATION_OPEN' WHEN _op='ASSESS' AND i.status='MANUAL_REVIEW' THEN 'MANUAL_REVIEW_OPEN' ELSE _op END,coalesce(nullif(why,''),i.reason));
INSERT INTO audit_log(actor_user_id,partner_id,action,entity_type,entity_id,metadata) VALUES(u,p,'PARTNER_INTAKE_'||_op,'partner_intake',i.id::text,jsonb_build_object('status',i.status,'location_id',l));
RETURN jsonb_build_object('id',i.id,'status',CASE WHEN _op='REJECT' THEN 'REJECTED' ELSE i.status END,'consultationId',i.consultation_id);
END $$;
REVOKE ALL ON FUNCTION public.partner_intake_command(text,uuid,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.partner_intake_command(text,uuid,jsonb) TO authenticated;